//! Native equivalent of scripts/embed-shell-integration.mjs.
//! The caller supplies the gateway package root; no process-wide cwd is used.
use std::{
    fs,
    io::{self, Read, Write},
    path::Path,
};

const BANNER: &str = r#"/**
 * AUTO-GENERATED FILE — DO NOT EDIT BY HAND.
 *
 * Source: `src/surfaces/shell-integration/*.sh|*.ps1`
 * Regenerate: `node scripts/embed-shell-integration.mjs`
 *
 * These constants are the packaging-proof fallback for the shell integration
 * scripts. `tsc` does not copy `.sh`/`.ps1` assets into `dist/`, so a
 * published/installed gateway (and the Tauri desktop bundle) can end up
 * without `dist/surfaces/shell-integration`. Without those files the terminal
 * silently ran with no OSC 633 integration, which broke prompt detection,
 * exit codes and background-command completion. The runtime now writes these
 * embedded copies to a cache directory whenever the packaged files are
 * missing, so integration always works.
 *
 * Generated by: scripts/embed-shell-integration.mjs
 */
"#;
const SCRIPTS: [(&str, &str); 3] = [
    ("bash.sh", "BASH_INTEGRATION_SCRIPT"),
    ("zsh.sh", "ZSH_INTEGRATION_SCRIPT"),
    ("pwsh.ps1", "PWSH_INTEGRATION_SCRIPT"),
];

// JSON.stringify on a JS string escapes controls, quotes and backslashes.
fn json_string(value: &str) -> String {
    let mut out = String::from("\"");
    for c in value.chars() {
        match c {
            '"' => out.push_str("\\\""),
            '\\' => out.push_str("\\\\"),
            '\u{8}' => out.push_str("\\b"),
            '\u{c}' => out.push_str("\\f"),
            '\n' => out.push_str("\\n"),
            '\r' => out.push_str("\\r"),
            '\t' => out.push_str("\\t"),
            c if c < '\u{20}' => out.push_str(&format!("\\u{:04x}", c as u32)),
            c => out.push(c),
        }
    }
    out.push('"');
    out
}

pub fn render(scripts: [&str; 3]) -> String {
    let mut out = BANNER.to_owned();
    for ((file, name), content) in SCRIPTS.iter().zip(scripts) {
        // JavaScript String.length counts UTF-16 code units, despite the label.
        out.push_str(&format!("\n/** Contents of `shell-integration/{file}` ({} bytes). */\nexport const {name}: string = [\n", content.encode_utf16().count()));
        for line in content.split('\n') {
            out.push_str(&format!("  {},\n", json_string(line)));
        }
        out.push_str("].join(\"\\n\");\n");
    }
    out.push_str("\n/** Map of integration script filename → embedded contents. */\nexport const SHELL_INTEGRATION_ASSETS: Readonly<Record<string, string>> = {\n  \"bash.sh\": BASH_INTEGRATION_SCRIPT,\n  \"zsh.sh\": ZSH_INTEGRATION_SCRIPT,\n  \"pwsh.ps1\": PWSH_INTEGRATION_SCRIPT,\n};\n");
    out
}

#[derive(Debug, PartialEq, Eq)]
pub enum Outcome {
    Written,
    UpToDate,
    Missing,
    OutOfDate,
}

#[derive(Debug)]
pub struct FileError {
    pub operation: &'static str,
    pub path: std::path::PathBuf,
    pub source: io::Error,
}

// Match Node's stable error headline for common filesystem failures. Node's
// runtime-specific stack and version footer are intentionally not reproduced.
impl std::fmt::Display for FileError {
    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        let detail = match self.source.kind() {
            io::ErrorKind::NotFound => Some(("ENOENT", "no such file or directory")),
            io::ErrorKind::PermissionDenied => Some(("EACCES", "permission denied")),
            io::ErrorKind::IsADirectory => Some(("EISDIR", "illegal operation on a directory")),
            io::ErrorKind::NotADirectory => Some(("ENOTDIR", "not a directory")),
            io::ErrorKind::AlreadyExists => Some(("EEXIST", "file already exists")),
            _ => None,
        };
        if let Some((code, description)) = detail {
            write!(f, "Error: {code}: {description}, {}", self.operation)?;
        } else {
            write!(f, "Error: {}, {}", self.source, self.operation)?;
        }
        if self.operation == "open" {
            write!(f, " '{}'", self.path.display())?;
        }
        Ok(())
    }
}

impl std::error::Error for FileError {
    fn source(&self) -> Option<&(dyn std::error::Error + 'static)> {
        Some(&self.source)
    }
}

pub fn run(package_root: &Path, check: bool) -> Result<Outcome, FileError> {
    let source = package_root.join("src/surfaces/shell-integration");
    let contents: Vec<String> = SCRIPTS
        .iter()
        .map(|(file, _)| {
            let path = source.join(file);
            let mut input = fs::File::open(&path).map_err(|source| FileError {
                operation: "open",
                path: path.clone(),
                source,
            })?;
            let mut bytes = Vec::new();
            input.read_to_end(&mut bytes).map_err(|source| FileError {
                operation: "read",
                path,
                source,
            })?;
            Ok(String::from_utf8_lossy(&bytes).into_owned())
        })
        .collect::<Result<_, _>>()?;
    let rendered = render([&contents[0], &contents[1], &contents[2]]);
    let output = package_root.join("src/surfaces/shell-integration-assets.ts");
    if check {
        // The JS script reports every read error as missing.
        return Ok(match fs::read(output) {
            Ok(current) if String::from_utf8_lossy(&current) == rendered => Outcome::UpToDate,
            Ok(_) => Outcome::OutOfDate,
            Err(_) => Outcome::Missing,
        });
    }
    let mut file = fs::File::create(&output).map_err(|source| FileError {
        operation: "open",
        path: output.clone(),
        source,
    })?;
    file.write_all(rendered.as_bytes())
        .map_err(|source| FileError {
            operation: "write",
            path: output,
            source,
        })?;
    Ok(Outcome::Written)
}

#[cfg(test)]
mod tests {
    use super::*;
    #[test]
    fn quoting_and_utf16_length_match_js() {
        let out = render(["😀\t\"\\\u{1}\n", "", ""]);
        assert!(out.contains("(7 bytes)"));
        assert!(out.contains("  \"😀\\t\\\"\\\\\\u0001\",\n  \"\","));
    }
    #[test]
    fn malformed_utf8_is_replaced_and_check_outcomes_are_reported() {
        let root = Path::new(env!("CARGO_MANIFEST_DIR"))
            .parent()
            .unwrap()
            .parent()
            .unwrap()
            .join(".jait/artifacts/gateway-rust")
            .join(format!("embed-test-{}", std::process::id()));
        let source = root.join("src/surfaces/shell-integration");
        fs::create_dir_all(&source).unwrap();
        fs::write(source.join("bash.sh"), b"bad\xff").unwrap();
        fs::write(source.join("zsh.sh"), b"").unwrap();
        fs::write(source.join("pwsh.ps1"), b"").unwrap();
        assert_eq!(run(&root, true).unwrap(), Outcome::Missing);
        assert_eq!(run(&root, false).unwrap(), Outcome::Written);
        let output = root.join("src/surfaces/shell-integration-assets.ts");
        assert!(fs::read_to_string(&output).unwrap().contains("bad�"));
        assert_eq!(run(&root, true).unwrap(), Outcome::UpToDate);
        fs::write(&output, b"bad\xff").unwrap();
        assert_eq!(run(&root, true).unwrap(), Outcome::OutOfDate);
        fs::remove_dir_all(root).unwrap();
    }
    #[test]
    fn source_and_output_errors_identify_operation_and_path() {
        let root = Path::new(env!("CARGO_MANIFEST_DIR"))
            .parent()
            .unwrap()
            .parent()
            .unwrap()
            .join(".jait/artifacts/gateway-rust")
            .join(format!("embed-error-test-{}", std::process::id()));
        let source = root.join("src/surfaces/shell-integration");
        fs::create_dir_all(&source).unwrap();
        let error = run(&root, true).unwrap_err();
        assert_eq!(error.operation, "open");
        assert!(
            error
                .to_string()
                .starts_with("Error: ENOENT: no such file or directory, open ")
        );
        assert_eq!(error.path, source.join("bash.sh"));
        for (file, _) in SCRIPTS {
            fs::write(source.join(file), "").unwrap();
        }
        let output = root.join("src/surfaces/shell-integration-assets.ts");
        fs::create_dir(&output).unwrap();
        let error = run(&root, false).unwrap_err();
        assert_eq!(error.operation, "open");
        assert_eq!(error.path, output);
        fs::remove_dir_all(root).unwrap();
    }
    #[test]
    fn repository_generated_asset_matches() {
        let root = Path::new(env!("CARGO_MANIFEST_DIR"))
            .parent()
            .unwrap()
            .join("gateway");
        assert_eq!(run(&root, true).unwrap(), Outcome::UpToDate);
    }
}
